<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\TrustedClient\Domain\ValueObject\Accessor\TrustedClientAllowedRedirectsUrlAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the TrustedClientAllowedRedirectsUrlAccessor trait.
 *
 * Covers null default, string/VO assignment via withUrl,
 * getUrl/url accessors, and isUrlChanged with/without original.
 */
class TrustedClientAllowedRedirectsUrlAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withUrl creates a new instance with the Url set
     * from a string value, and getUrl returns the primitive string.
     */
    public function testWithUrlFromString(): void
    {
        // Arrange
        $holder = new ImplWithTrustedClientAllowedRedirectsUrlAccessorUnitTest();

        // Act
        $result = $holder->withUrl('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->getUrl());
    }
    /**
     * Asserts that withurl has access to the value object
     * from a string value, and getUrl returns the primitive string.
     */
    public function testWithUrlFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithTrustedClientAllowedRedirectsUrlAccessorUnitTest();

        // Act
        $result = $holder->withUrl('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->url()->value());
    }
    public function testChangedUrl(): void
    {
        // Arrange
        $holder = new ImplWithTrustedClientAllowedRedirectsUrlAccessorUnitTest()->withUrl('one');
        $original = $holder->withUrl('one');
        $same = $holder->withUrl('one');
        $modified = $holder->withUrl('other');

        // Act
        $withSame = $original->isUrlChanged($same);
        $withDiferent = $original->isUrlChanged($modified);

        // Assert
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithTrustedClientAllowedRedirectsUrlAccessorUnitTest
{
    use TrustedClientAllowedRedirectsUrlAccessor;
}
